CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) UNIQUE NOT NULL, hashed_password VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT NOW()); CREATE TABLE IF NOT EXISTS wallets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, balance DECIMAL(15,2) DEFAULT 0.00 NOT NULL, currency VARCHAR(3) DEFAULT 'INR', is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW()); CREATE TABLE IF NOT EXISTS transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sender_wallet_id UUID REFERENCES wallets(id), receiver_wallet_id UUID REFERENCES wallets(id), amount DECIMAL(15,2) NOT NULL, status VARCHAR(20) DEFAULT 'pending', created_at TIMESTAMP DEFAULT NOW()); CREATE TABLE IF NOT EXISTS ledger_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID REFERENCES transactions(id), wallet_id UUID REFERENCES wallets(id), entry_type VARCHAR(10) NOT NULL, amount DECIMAL(15,2) NOT NULL, balance_before DECIMAL(15,2) NOT NULL, balance_after DECIMAL(15,2) NOT NULL, created_at TIMESTAMP DEFAULT NOW());
